    <script>
    // JavaScript to handle button click and toggle content visibility
    var buttons = document.getElementsByClassName('toggleButton');

    for (var i = 0; i < buttons.length; i++) {
        buttons[i].addEventListener('click', function(event) {
            var button = event.target;
            var content = button.parentElement.querySelector('.hiddenContent');

            // Toggle the class
            if (content) {
                content.classList.toggle('hidden');
                button.textContent = content.classList.contains('hidden') ? 'Read More' : 'Read Less';
            }
        });
    }
    </script>

